static char *make_big_text(size_t target)
{
    static char buf[32768];
    size_t n = 0;
    const char *cjk = "\xe6\xb7\xb1";      /* 深, 3 bytes */
    const char *emoji = "\xf0\x9f\x94\xa7"; /* 🔧, 4 bytes */
    while (n + 16 < target && n + 16 < sizeof(buf)) {
        n += (size_t)snprintf(buf + n, sizeof(buf) - n,
