cJSON* build_openai_tools_array(const char* tools_json)
{
    if (!tools_json) {
        return NULL;
    }

    cJSON* tools_spec = cJSON_Parse(tools_json);

    if (!tools_spec || !cJSON_IsArray(tools_spec)) {
        cJSON_Delete(tools_spec);
        return NULL;
    }

    cJSON* tools_arr = cJSON_CreateArray();
    cJSON* tool_def;

