            cJSON_AddItemToObject(func, "parameters", empty);
        }

        cJSON_AddItemToObject(wrapper, "function", func);
        cJSON_AddItemToArray(tools_arr, wrapper);
    }

    cJSON_Delete(tools_spec);
    return tools_arr;
}

