    bool post_is_static = false;
    char *post_data = (tree_ok == OK)
        ? req_serialize(body, &post_is_static) : NULL;

    /* give the borrowed trees back before tearing the body down */
    cJSON_DetachItemViaPointer(body, messages);
    {
